/**
 * Kumva EndFlow Node
 * Closes campaign sessions and generates summary reports
 */

module.exports = function(RED) {
  const SessionManager = require('kumva-insights/utils/session-manager');
  const DataStorage = require('kumva-insights/utils/data-storage');
  const ConfigManager = require('kumva-insights/utils/config-manager');
  const helpers = require('kumva-insights/utils/helpers');

  // Global managers
  let globalSessionManager = null;
  let globalDataStorage = null;
  let globalConfigManager = null;

  /**
   * Initialize global dependencies
   */
  async function initializeGlobals() {
    if (!globalSessionManager) {
      globalConfigManager = new ConfigManager();
      
      globalSessionManager = new SessionManager(globalConfigManager.getRedisConfig());
      await globalSessionManager.initialize();

      globalDataStorage = new DataStorage(globalConfigManager.getStoragePath());
    }

    return {
      sessionManager: globalSessionManager,
      dataStorage: globalDataStorage,
      configManager: globalConfigManager
    };
  }

  function KumvaEndFlowNode(config) {
    RED.nodes.createNode(this, config);
    const node = this;

    // Initialize globals
    initializeGlobals().catch(error => {
      node.error(`Failed to initialize: ${error.message}`);
    });

    /**
     * Generate session summary
     */
    function generateSessionSummary(sessionData) {
      const summary = {
        sessionId: sessionData.sessionId,
        phoneNumber: sessionData.phoneNumber,
        campaignId: sessionData.campaignId,
        duration: 0,
        responseCount: sessionData.responseCount || 0,
        status: sessionData.status || 'completed',
        startedAt: sessionData.createdAt || sessionData.metadata?.startedAt,
        completedAt: new Date().toISOString(),
        responses: sessionData.responses || []
      };

      // Calculate duration
      if (summary.startedAt && summary.completedAt) {
        const start = new Date(summary.startedAt);
        const end = new Date(summary.completedAt);
        summary.duration = Math.round((end - start) / 1000); // seconds
      }

      return summary;
    }

    /**
     * Generate campaign report
     */
    async function generateCampaignReport(campaignId, sessionSummaries) {
      const totalSessions = sessionSummaries.length;
      const completedSessions = sessionSummaries.filter(s => s.status === 'completed').length;
      const totalResponses = sessionSummaries.reduce((sum, s) => sum + s.responseCount, 0);

      const avgDuration = totalSessions > 0
        ? Math.round(sessionSummaries.reduce((sum, s) => sum + s.duration, 0) / totalSessions)
        : 0;

      return {
        campaignId: campaignId,
        generatedAt: new Date().toISOString(),
        summary: {
          totalSessions: totalSessions,
          completedSessions: completedSessions,
          successRate: totalSessions > 0 ? (completedSessions / totalSessions * 100).toFixed(2) + '%' : '0%',
          totalResponses: totalResponses,
          averageDuration: avgDuration + 's'
        },
        sessions: sessionSummaries
      };
    }

    /**
     * Send notification if configured
     */
    async function sendNotification(msg, status, details) {
      if (!config.sendNotification || !config.notificationUrl) {
        return;
      }

      try {
        const notification = {
          flowEndTime: new Date().toISOString(),
          sessionId: msg.sessionId,
          campaignId: msg.campaignId,
          status: status,
          details: details
        };

        // In production, would make HTTP POST here
        node.log(`Notification: ${JSON.stringify(notification)}`);
      } catch (error) {
        node.warn(`Failed to send notification: ${error.message}`);
      }
    }

    /**
     * Handle incoming messages
     */
    node.on('input', async function(msg) {
      try {
        const { sessionManager, dataStorage } = await initializeGlobals();

        // Validate required fields
        if (!msg.sessionId) {
          node.error('Missing sessionId in message');
          node.status({
            fill: 'red',
            shape: 'ring',
            text: 'No sessionId'
          });
          return;
        }

        node.status({
          fill: 'blue',
          shape: 'dot',
          text: 'Closing session...'
        });

        // Get session data
        const sessionResult = await sessionManager.getSession(msg.sessionId);
        
        let sessionData = null;
        let summary = null;

        if (sessionResult.exists) {
          sessionData = sessionResult.data;
          
          // Generate summary
          summary = generateSessionSummary(sessionData);

          // Determine end status
          let endStatus = 'completed';
          if (msg.flowError) {
            endStatus = 'error';
          } else if (msg.flowSkipped) {
            endStatus = 'skipped';
          }

          // Update session with end status
          await sessionManager.updateSession(msg.sessionId, {
            status: endStatus,
            endedAt: new Date().toISOString(),
            endReason: msg.endReason || 'normal',
            finalMessage: msg.finalMessage || null
          });

          // Store final summary in data storage if enabled
          if (config.storeReport && msg.campaignId) {
            const reportKey = `${msg.campaignId}:${msg.sessionId}`;
            await dataStorage.addResponse(
              msg.campaignId,
              msg.sessionId,
              {
                type: 'session-summary',
                content: JSON.stringify(summary)
              }
            );
          }
        } else {
          node.warn(`Session not found: ${msg.sessionId}`);
        }

        // Delete session from Redis if configured
        if (config.deleteSession) {
          const deleteResult = await sessionManager.deleteSession(msg.sessionId);
          if (deleteResult.success) {
            node.log(`Session deleted: ${msg.sessionId}`);
          }
        }

        // Send notification if configured
        if (config.sendNotification) {
          await sendNotification(msg, sessionData?.status || 'unknown', summary);
        }

        // Debug logging
        if (config.debugMode && summary) {
          node.log(`Session completed:`);
          node.log(`  Phone: ${summary.phoneNumber}`);
          node.log(`  Duration: ${summary.duration}s`);
          node.log(`  Responses: ${summary.responseCount}`);
        }

        // Prepare output message
        const outputMsg = {
          ...msg,
          flowStatus: 'ended',
          sessionSummary: summary,
          _kumva: {
            ...msg._kumva,
            endedAt: new Date().toISOString(),
            sessionSummary: summary
          }
        };

        node.status({
          fill: 'green',
          shape: 'dot',
          text: 'Session closed'
        });

        // Send output
        node.send(outputMsg);

      } catch (error) {
        node.error(`EndFlow error: ${error.message}`);
        node.status({
          fill: 'red',
          shape: 'ring',
          text: 'Error closing session'
        });

        msg.flowStatus = 'error';
        msg.flowError = error.message;
        node.send(msg);
      }
    });

    /**
     * Handle close/cleanup
     */
    node.on('close', function(done) {
      // Nothing to clean up
      done();
    });

    // Initialize status
    node.status({
      fill: 'yellow',
      shape: 'ring',
      text: 'Ready'
    });
  }

  /**
   * Campaign Report Generator - HTTP endpoint
   */
  function KumvaCampaignReportHandler() {
    RED.httpAdmin.get('/kumva/campaign/:campaignId/report', async function(req, res) {
      try {
        const campaignId = req.params.campaignId;
        
        const { dataStorage } = await initializeGlobals();

        // Get all sessions for campaign
        const sessionsResult = await dataStorage.getCampaignSessions(campaignId);

        if (!sessionsResult.success) {
          return res.status(500).json({
            success: false,
            error: 'Failed to retrieve sessions'
          });
        }

        const sessions = sessionsResult.sessions || [];
        const summaries = sessions.map(session => {
          return {
            sessionId: session.sessionId,
            phoneNumber: session.phoneNumber,
            responseCount: session.responses?.length || 0,
            status: session.metadata?.status || 'active',
            duration: 0,
            startedAt: session.metadata?.startedAt,
            completedAt: session.metadata?.lastUpdated
          };
        });

        // Generate report (using the node's report generator)
        // Note: This is a simplified version
        const report = {
          campaignId: campaignId,
          generatedAt: new Date().toISOString(),
          summary: {
            totalSessions: summaries.length,
            completedSessions: summaries.filter(s => s.status === 'completed').length,
            totalResponses: summaries.reduce((sum, s) => sum + s.responseCount, 0)
          },
          sessions: summaries
        };

        res.json(report);

      } catch (error) {
        RED.log.error(`Report generation error: ${error.message}`);
        res.status(500).json({
          success: false,
          error: error.message
        });
      }
    });
  }

  RED.nodes.registerType('kumva-end-flow', KumvaEndFlowNode);

  // Register report handler
  RED.events.once('flows:add', function() {
    KumvaCampaignReportHandler();
  });
};